import React, { useState } from "react";
import { StyleSheet, View, Text } from "react-native";
import Backbutton from "../components/Backbutton";
import { CurrentRenderContext, useNavigation } from "@react-navigation/native";
import Doctor from "../screens/yuvaservices/opd/doctors/Doctor";
import { Dropdown } from "react-native-element-dropdown";
import { createMaterialTopTabNavigator } from "@react-navigation/material-top-tabs";
import AppointmentNav from "./AppointmentNav";
import Entypo from "react-native-vector-icons/Entypo";
const Tab = createMaterialTopTabNavigator();

const OPDNavigation = () => {
  const navigation = useNavigation();
  const [value, setValue] = useState(null);
  const [isFocus, setIsFocus] = useState(false);
  const goBack = () => navigation.goBack();
  return (
    <View>
      <View className="flex-row items-center h-[62px] bg-[#1D2334] pl-[10px]">
        <Backbutton onPress={goBack} color="white" size={20} />
        <Text className="text-white text-center text-base ml-[20px]">OPD</Text>

        <View style={styles.outer}>
          <Dropdown
            style={[styles.dropdown, isFocus && { borderColor: "white" }]}
            placeholderStyle={styles.placeholderStyle}
            // selectedTextStyle={styles.selectedTextStyle}
            inputSearchStyle={styles.inputSearchStyle}
            // iconStyle={styles.iconStyle}
            // data={data}
            search
            // maxHeight={300}
            labelField="label"
            valueField="value"
            placeholder={!isFocus ? "location" : "..."}
            searchPlaceholder="Search..."
            value={value}
            onFocus={() => setIsFocus(true)}
            onBlur={() => setIsFocus(false)}
            onChange={(item) => {
              setValue(item.value);
              setIsFocus(false);
            }}
            renderLeftIcon={() => (
              <Entypo
                style={styles.icon}
                color={isFocus ? "blue" : "black"}
                name="location-pin"
                size={20}
              />
            )}
          />
          />
        </View>

        {/* <view className="flex-end">
          <Text className="text-white text-center text-base mr-[100px]">
            location
          </Text>
        </view> */}
      </View>
      <Tab.Navigator
        className="flex"
        screenOptions={{
          tabBarLabelStyle: { fontSize: 16, marginTop: 15 },
          tabBarStyle: { color: "#1D2334", height: 70 },
        }}
      >
        <Tab.Screen name="Doctor" component={Doctor} />
        <Tab.Screen name="Appointments" component={AppointmentNav} />
      </Tab.Navigator>
    </View>
  );
};

export default OPDNavigation;
const styles = StyleSheet.create({
  outer: {
    paddingLeft: 150,
    marginTop: 20,
  },
  container: {
    backgroundColor: "white",
    padding: 16,
  },
  dropdown: {
    backgroundColor: "white",

    height: 26,
    borderColor: "white",
    borderWidth: 1,
    borderRadius: 8,

    // position: absolute,
    paddingHorizontal: 10,
  },
  icon: {
    marginRight: 10,
  },
  //   label: {
  //     position: "absolute",
  //     backgroundColor: "white",
  //     left: 22,
  //     top: 8,
  //     zIndex: 999,
  //     paddingHorizontal: 8,
  //     fontSize: 14,
  //   },
  //  s
  // selectedTextStyle: {
  //   fontSize: 16,
  // },
  // iconStyle: {
  //   width: 20,
  //   height: 20,
  // },
  inputSearchStyle: {
    height: 40,
    fontSize: 16,
  },
});
